const medical = $('Medical Validator').first().json.output ?? {};
const brand = $('Brand Validator').first().json.output ?? {};

const medicalPassed = medical.passed === true;
const brandPassed = brand.passed === true;

const medicalIssues = Array.isArray(medical.issues) ? medical.issues : [];
const medicalCriticalIssues = Array.isArray(medical.critical_issues) ? medical.critical_issues : [];
const brandIssues = Array.isArray(brand.issues) ? brand.issues : [];
const brandCriticalIssues = Array.isArray(brand.critical_issues) ? brand.critical_issues : [];

const medicalScore = Number(medical.score) || 0;
const brandScore = Number(brand.score) || 0;

const bothMet = medicalScore >= 0.9 && brandScore >= 0.9;
const hasMedicalIssues = !medicalPassed || medicalIssues.length > 0 || medicalCriticalIssues.length > 0;
const hasBrandIssues = !brandPassed || brandIssues.length > 0 || brandCriticalIssues.length > 0;
const hasAnyIssue = hasMedicalIssues || hasBrandIssues;

const decision = bothMet && !hasAnyIssue
  ? "APPROVE_FOR_HUMAN_REVIEW"
  : "REWORK";

return {
  json: {
    medical_passed: medicalPassed,
    medical_score: medicalScore,
    medical_issues: medicalIssues,
    medical_critical_issues: medicalCriticalIssues,
    brand_passed: brandPassed,
    brand_score: brandScore,
    brand_issues: brandIssues,
    brand_critical_issues: brandCriticalIssues,
    has_medical_issues: hasMedicalIssues,
    has_brand_issues: hasBrandIssues,
    has_any_issue: hasAnyIssue,
    both_met: bothMet,
    decision
  }
};

const toArr = (v) => Array.isArray(v) ? v : [];
const join = (v) => {
  const a = toArr(v);
  if (a.length === 0) return "None";
  return a.map((x, i) => (i + 1) + ". " + (typeof x === "string" ? x : JSON.stringify(x))).join("\n");
};

let refined = null;
try { refined = $('content refinement agent').last().json.output; } catch (e) { refined = null; }

let med = null;
try { med = $('Re-Medical Validator').last().json.output; } catch (e) { med = null; }
let brand = null;
try { brand = $('Re-Brand Validator').last().json.output; } catch (e) { brand = null; }

if (!med) { try { med = $('Medical Validator').first().json.output; } catch (e) { med = {}; } }
if (!brand) { try { brand = $('Brand Validator').first().json.output; } catch (e) { brand = {}; } }

let content = refined;
if (content === null || content === undefined || content === "") {
  try { content = $('Content Generation Agent').first().json.output; } catch (e) { content = ""; }
}

const ef = $('Edit Fields').first().json;
const incomingAttempt = Number($json.refinement_attempt ?? 0);

return [{ json: {
  current_content: content,
  refinement_attempt: incomingAttempt,
  medical_passed: med.passed === true,
  medical_score: Number(med.score) || 0,
  medical_issues: toArr(med.issues),
  medical_critical_issues: toArr(med.critical_issues),
  medical_issues_text: join(med.issues),
  medical_critical_text: join(med.critical_issues),
  brand_passed: brand.passed === true,
  brand_score: Number(brand.score) || 0,
  brand_issues: toArr(brand.issues),
  brand_critical_issues: toArr(brand.critical_issues),
  brand_issues_text: join(brand.issues),
  brand_critical_text: join(brand.critical_issues),
  content_type: ef.content_type,
  topic: ef.topic,
  target_audience: ef.target_audience,
  platform: ef.platform,
  language: ef.language,
  tone: ef.tone,
  campaign_objective: ef.campaign_objective,
  additional_instructions: ef.additional_instructions
}}];

