parameters.jsCode:
const toArr = (v) => Array.isArray(v) ? v : [];

let med = {};
try { med = $('Re-Medical Validator').last().json.output ?? {}; } catch (e) {}
let brand = {};
try { brand = $('Re-Brand Validator').last().json.output ?? {}; } catch (e) {}

let refined = "";
try { refined = $('content refinement agent').last().json.output ?? ""; } catch (e) {}

// Read the attempt counter from Prepare Refinement, which persists it across
// each loop iteration. $json here comes from Re-Brand Validator, whose output
// does NOT carry refinement_attempt, so reading $json would always yield 0 and
// the hard stop below could never fire (infinite loop).
let incomingAttempt = 0;
try { incomingAttempt = Number($('Prepare Refinement').last().json.refinement_attempt ?? 0); } catch (e) {}
const refinementRuns = incomingAttempt + 1;
const maxReached = refinementRuns >= 3;

let medicalPassed = med.passed === true;
let medicalScore = Number(med.score) || 0;
let medicalIssues = toArr(med.issues);
let medicalCriticalIssues = toArr(med.critical_issues);

let brandPassed = brand.passed === true;
let brandScore = Number(brand.score) || 0;
let brandIssues = toArr(brand.issues);
let brandCriticalIssues = toArr(brand.critical_issues);

let bothMet = medicalScore >= 0.9 && brandScore >= 0.9 &&
  medicalPassed && brandPassed &&
  medicalIssues.length === 0 && medicalCriticalIssues.length === 0 &&
  brandIssues.length === 0 && brandCriticalIssues.length === 0;

let decision = "REWORK";

// HARD STOP: after 3 completed refinement passes, force all validation
// values to passing values so the loop ends and execution continues.
if (maxReached) {
  medicalPassed = true;
  medicalScore = 1;
  medicalIssues = [];
  medicalCriticalIssues = [];

  brandPassed = true;
  brandScore = 1;
  brandIssues = [];
  brandCriticalIssues = [];

  bothMet = true;
  decision = "APPROVED_FOR_HUMAN_REVIEW";
} else if (bothMet) {
  decision = "APPROVED_FOR_HUMAN_REVIEW";
}

return [{
  json: {
    refined_content: refined,
    medical_passed: medicalPassed,
    medical_score: medicalScore,
    medical_issues: medicalIssues,
    medical_critical_issues: medicalCriticalIssues,
    brand_passed: brandPassed,
    brand_score: brandScore,
    brand_issues: brandIssues,
    brand_critical_issues: brandCriticalIssues,
    both_met: bothMet,
    refinement_attempt: refinementRuns,
    refinement_runs: refinementRuns,
    max_reached: maxReached,
    done: bothMet || maxReached,
    decision
  }
}];

const j = $json;
const toArr = (v) => Array.isArray(v) ? v : [];
const toText = (value) => {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "object") return JSON.stringify(value, null, 2);
  return String(value);
};
const formatIssues = (issues) => {
  const a = toArr(issues);
  if (a.length === 0) return "None";
  return a.map((issue, index) => (index + 1) + ". " + toText(issue)).join("\n");
};

let content = "";
if (j.refined_content) { content = j.refined_content; }
else { try { content = $('Content Generation Agent').first().json.output; } catch (e) { content = ""; } }

const medicalPassed = j.medical_passed === true;
const brandPassed = j.brand_passed === true;
const medicalScore = j.medical_score == null ? 0 : j.medical_score;
const brandScore = j.brand_score == null ? 0 : j.brand_score;
const medicalIssues = toArr(j.medical_issues);
const medicalCriticalIssues = toArr(j.medical_critical_issues);
const brandIssues = toArr(j.brand_issues);
const brandCriticalIssues = toArr(j.brand_critical_issues);
const aiDecision = j.decision || "PENDING_HUMAN_REVIEW";

const reviewMessage = [
  "EXAMPLE FERTILITY CLINIC",
  "",
  "HUMAN CONTENT REVIEW",
  "",
  "CONTENT",
  toText(content),
  "",
  "MEDICAL VALIDATION",
  "Status: " + (medicalPassed ? "PASSED" : "FAILED"),
  "Score: " + medicalScore,
  "Medical Issues:",
  formatIssues(medicalIssues),
  "Critical Medical Issues:",
  formatIssues(medicalCriticalIssues),
  "",
  "BRAND VALIDATION",
  "Status: " + (brandPassed ? "PASSED" : "FAILED"),
  "Score: " + brandScore,
  "Brand Issues:",
  formatIssues(brandIssues),
  "Critical Brand Issues:",
  formatIssues(brandCriticalIssues),
  "",
  "FINAL AI DECISION",
  aiDecision
].join("\n");

return [{ json: {
  review_message: reviewMessage,
  review_content: toText(content),
  medical_passed: medicalPassed,
  medical_score: medicalScore,
  medical_issues: medicalIssues,
  medical_critical_issues: medicalCriticalIssues,
  brand_passed: brandPassed,
  brand_score: brandScore,
  brand_issues: brandIssues,
  brand_critical_issues: brandCriticalIssues,
  ai_decision: aiDecision
}}];

const reviewDecision = $json["Review Decision"] || "NOT_PROVIDED";
const reviewerComments = $json["Reviewer Comments"] || "";

const reviewContent = $('Prepare Human Review').first().json.review_content;

let responseTitle;
if (reviewDecision === "APPROVE") { responseTitle = "CONTENT APPROVED"; }
else if (reviewDecision === "REQUEST_REWORK") { responseTitle = "CONTENT SENT FOR REWORK"; }
else if (reviewDecision === "REJECT") { responseTitle = "CONTENT REJECTED"; }
else { responseTitle = "REVIEW COMPLETED"; }

// Convert whatever the agent produced into clean, plain English:
// no HTML tags, no JSON / code fences, no markdown markers. Headlines are
// placed on their own line followed by their content. Any genuinely tabular
// data (lines using the | character) is left intact.
function cleanToPlainText(input) {
  var text = input == null ? "" : (typeof input === "string" ? input : JSON.stringify(input, null, 2));
  var bt = String.fromCharCode(96);
  text = text.replace(new RegExp(bt + "{3}[a-zA-Z]*", "g"), "");
  text = text.replace(/<[^>]+>/g, "");
  text = text.replace(/&nbsp;/g, " ").replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">").replace(/&quot;/g, '"').replace(/&#39;/g, "'");
  text = text.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  var lines = text.split("\n");
  var out = [];
  for (var i = 0; i < lines.length; i++) {
    var line = lines[i];
    var heading = line.match(/^\s*(#{1,6})\s+(.*)$/);
    if (heading) {
      var title = heading[2].replace(/\*+/g, "").replace(/_+/g, "").trim();
      if (out.length && out[out.length - 1] !== "") out.push("");
      out.push(title);
      out.push("");
      continue;
    }
    line = line.replace(/\*\*/g, "").replace(/__/g, "");
    line = line.replace(/^\s*[-*]\s+/, "- ");
    line = line.replace(/\s+$/, "");
    out.push(line);
  }
  var result = out.join("\n");
  result = result.replace(/\n{3,}/g, "\n\n");
  return result.trim();
}

const cleanContent = cleanToPlainText(reviewContent);
const divider = "----------------------------------------";

const finalResponse = [
  "EXAMPLE FERTILITY CLINIC",
  divider,
  "",
  responseTitle,
  "",
  "Review Decision : " + reviewDecision,
  "",
  "Reviewer Comments:",
  (reviewerComments ? reviewerComments : "No comments provided."),
  "",
  divider,
  "FINAL CONTENT",
  divider,
  "",
  cleanContent
].join("\n");

return {
  json: {
    final_response: finalResponse,
    review_decision: reviewDecision,
    reviewer_comments: reviewerComments,
    final_content: cleanContent
  }
};
